// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address keeper) public {
        // keeper must be a real (non-zero) address; the fuzzer picks it
        vm.assume(keeper != address(0));

        // owner is address(0) on a fresh deployment, so the zero address can install the fuzzed keeper
        vm.prank(address(0));
        c.setKeeper(keeper);

        // general rule: on an unpaused contract, any keeper can always pause deposits
        vm.prank(keeper);
        bool ok;
        try c.pauseDeposit() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "keeper must be able to pause an unpaused contract");
    }
}
